package dev.pocketengine.ui
import org.json.JSONObject
import org.junit.Test
import org.junit.Assert.*
class ModelStreamDraftsTest {
 private fun task(status:String="running",run:String="run")=UiTask("task","goal",status,"canonical", "capabilities",1,JSONObject().put("runId",run).put("coordinatorEpoch",1))
 private fun event(kind:String,sequence:Long=1,request:String="request",generation:Long=1,text:String="",discard:Boolean=false)=JSONObject().put("taskId","task").put("runId","run").put("coordinatorEpoch",1).put("presentationRevision",generation).put("stream",JSONObject().put("kind",kind).put("requestId",request).put("sequence",sequence).put("provider","openai_chat").put("pauseRevision",0).put("provisional",kind=="text_delta").put("taskCompleted",false).also{if(kind=="text_delta")it.put("text",text);if(discard)it.put("discardDraft",true)})
 @Test fun completedKeepsOnlyProvisionalPreviewAndCannotChangeTaskOrMessages(){val t=task();var drafts=ModelStreamDrafts.accept(emptyMap(),event("started"),listOf(t));drafts=ModelStreamDrafts.accept(drafts,event("text_delta",2,text="draft text"),listOf(t));drafts=ModelStreamDrafts.accept(drafts,event("completed",3),listOf(t));assertEquals("draft text",drafts["task"]!!.text);assertTrue(drafts["task"]!!.turnEnded);assertEquals("running",t.status);assertEquals("canonical",t.summary);assertTrue(ModelStreamDrafts.retain(drafts,listOf(task("failed"))).isEmpty())}
 @Test fun lateOldRequestDiscardAndStartedCannotReplaceNewerPresentation(){var d=ModelStreamDrafts.accept(emptyMap(),event("started"),listOf(task()));d=ModelStreamDrafts.accept(d,event("started",request="new",generation=2),listOf(task()));d=ModelStreamDrafts.accept(d,event("text_delta",2,"new",2,"new text"),listOf(task()));d=ModelStreamDrafts.accept(d,event("cancelled",9,discard=true),listOf(task()));d=ModelStreamDrafts.accept(d,event("started"),listOf(task()));assertEquals("new text",d["task"]!!.text)}
 @Test fun missingStartWrongRunDuplicateAndSequenceGapNeverAppend(){assertTrue(ModelStreamDrafts.accept(emptyMap(),event("text_delta",2,text="no start"),listOf(task())).isEmpty());val d=ModelStreamDrafts.accept(emptyMap(),event("started"),listOf(task()));assertEquals(d,ModelStreamDrafts.accept(d,event("text_delta",1,text="duplicate"),listOf(task())));assertTrue(ModelStreamDrafts.accept(d,event("text_delta",3,text="gap"),listOf(task())).isEmpty());assertTrue(ModelStreamDrafts.retain(d,listOf(task(run="replacement"))).isEmpty())}
 @Test fun displayBoundPreservesUnicodeAndMarksTruncationWithoutTouchingCanonicalData(){var d=ModelStreamDrafts.accept(emptyMap(),event("started"),listOf(task()));for(i in 2L..18L)d=ModelStreamDrafts.accept(d,event("text_delta",i,text="x".repeat(2048)),listOf(task()));assertEquals(ModelStreamDrafts.MAX_CHARS,d["task"]!!.text.length);assertTrue(d["task"]!!.truncated);assertTrue(ModelStreamDrafts.accept(d,event("cancelled",19,discard=true),listOf(task())).isEmpty())}
 @Test fun interruptedAttemptRemainsSeparateFromNewResponseAndLateOldEventsCannotDuplicateIt(){var d=ModelStreamDrafts.accept(emptyMap(),event("started"),listOf(task()));d=ModelStreamDrafts.accept(d,event("text_delta",2,text="old partial"),listOf(task()));d=ModelStreamDrafts.accept(d,event("failed",3),listOf(task()));assertTrue(d["task"]!!.failed);d=ModelStreamDrafts.accept(d,event("started",request="retry",generation=2),listOf(task()));d=ModelStreamDrafts.accept(d,event("text_delta",2,"retry",2,"new final"),listOf(task()));d=ModelStreamDrafts.accept(d,event("text_delta",4,text="late old"),listOf(task()));assertEquals("new final",d["task"]!!.text);assertEquals(listOf(InterruptedModelAttempt("request","old partial")),d["task"]!!.interrupted);assertFalse(d["task"]!!.failed)}

}
